#!/usr/bin/env node
/**
 * CAIRN — the eight Play Store screenshots, captured from the running game.
 *
 *   node scripts/cairn-store-shots.mjs
 *
 * 1080x1920, which is the size Play wants and the size a 1080p phone actually
 * is. Every frame is the real game in a real browser at a real device pixel
 * ratio — nothing here is a mockup, and the tower in each shot was generated by
 * the shipped generator from a fixed seed.
 *
 * Each gets a caption overlay. Play does not require captions and every
 * competent listing has them, because the first two screenshots are the only
 * ones most people see and an unexplained dark image is a scroll.
 *
 * THE FIRST SHOT IS THE TOWER. It is the most striking image this game has and
 * the only one that explains the hook without a word.
 */
import { chromium } from 'playwright';
import { spawn } from 'node:child_process';
import { setTimeout as delay } from 'node:timers/promises';
import { mkdirSync } from 'node:fs';

const PORT = 4203;
const OUT = 'store/screenshots';
const W = 1080, H = 1920;
mkdirSync(OUT, { recursive: true });

const server = spawn('npx', ['vite', 'preview', '--port', String(PORT), '--host', '127.0.0.1'],
  { stdio: ['ignore', 'pipe', 'pipe'] });
server.stdout.on('data', () => {});
const shutdown = () => { try { server.kill('SIGTERM'); } catch { /* gone */ } };
process.on('exit', shutdown);
for (let i = 0; i < 80; i++) {
  try { if ((await fetch(`http://127.0.0.1:${PORT}/cairn/`)).ok) break; } catch { /* not up */ }
  await delay(400);
}

const browser = await chromium.launch({
  executablePath: '/opt/pw-browsers/chromium',
  args: ['--headless=new', '--use-gl=angle', '--use-angle=swiftshader',
    '--enable-unsafe-swiftshader', '--mute-audio'],
});

// 540x960 at dpr 2 gives a 1080x1920 backing store — a real phone aspect at the
// exact pixel size Play asks for.
const page = await browser.newPage({
  viewport: { width: W / 2, height: H / 2 },
  deviceScaleFactor: 2, isMobile: true, hasTouch: true,
});
await page.goto(`http://127.0.0.1:${PORT}/cairn/`, { waitUntil: 'load' });
await page.waitForFunction(() => !!window.CAIRN);

/**
 * Draw a caption band over a screenshot and return the composited PNG.
 *
 * Done in the page so the type is rendered by the same engine as the game's,
 * and so the band uses the design tokens rather than a second set of colours.
 *
 * @param {Buffer} shot
 * @param {string} line
 * @param {'top'|'bottom'} where
 * @returns {Promise<Buffer>}
 */
async function caption(shot, line, where = 'top') {
  const b64 = shot.toString('base64');
  const out = await page.evaluate(async ({ b64, line, where, W, H }) => {
    const img = new Image();
    img.src = `data:image/png;base64,${b64}`;
    await img.decode();
    const cv = document.createElement('canvas');
    cv.width = W; cv.height = H;
    const c = /** @type {CanvasRenderingContext2D} */ (cv.getContext('2d'));
    c.drawImage(img, 0, 0, W, H);

    const bandH = 300;
    const y = where === 'top' ? 0 : H - bandH;
    const g = c.createLinearGradient(0, y, 0, y + bandH);
    if (where === 'top') {
      g.addColorStop(0, 'rgba(5,7,12,0.96)');
      g.addColorStop(1, 'rgba(5,7,12,0)');
    } else {
      g.addColorStop(0, 'rgba(5,7,12,0)');
      g.addColorStop(1, 'rgba(5,7,12,0.96)');
    }
    c.fillStyle = g;
    c.fillRect(0, y, W, bandH);

    c.textAlign = 'center';
    c.fillStyle = '#E8EFF3';
    c.font = '300 46px ui-sans-serif, system-ui, sans-serif';
    c.letterSpacing = '3px';
    // Wrap at ~26 characters so a caption is never a single long line.
    const words = line.split(' ');
    /** @type {string[]} */
    const lines = [];
    let cur = '';
    for (const w of words) {
      if ((cur + ' ' + w).trim().length > 26) { lines.push(cur.trim()); cur = w; }
      else cur += ' ' + w;
    }
    if (cur.trim()) lines.push(cur.trim());
    const baseY = where === 'top' ? 108 : H - bandH + 150;
    lines.forEach((l, i) => c.fillText(l, W / 2, baseY + i * 58));
    return cv.toDataURL('image/png');
  }, { b64, line, where, W, H });
  return Buffer.from(out.split(',')[1], 'base64');
}

/**
 * @param {string} name
 * @param {string} line
 * @param {'top'|'bottom'} [where]
 */
async function shoot(name, line, where = 'top') {
  const raw = await page.screenshot();
  const done = await caption(raw, line, where);
  const { writeFileSync } = await import('node:fs');
  writeFileSync(`${OUT}/${name}.png`, done);
  console.log(`  ${name.padEnd(22)} ${line}`);
}

/** Build a tower of `n` bodies from a fixed seed, and stand the player on it. */
async function tower(n, best) {
  await page.evaluate(({ n, best }) => {
    const { sim, camera } = window.CAIRN;
    sim.reset(true);
    sim.phase = 1;
    let s = 20260730;
    const r = () => { s = (s * 1103515245 + 12345) & 0x7fffffff; return (s % 10000) / 10000; };
    for (let i = 0; i < n; i++) {
      sim.world.corpse(16 + r() * 68, 10 + i * (best / n), (r() - 0.5) * 1.1, i & 3, 0, i);
    }
    sim.deaths = n;
    sim.best = best;
    sim.world.generate(best + 400);
    camera.y = best * 0.5;
  }, { n, best });
  await delay(400);
}

console.log('CAIRN store screenshots\n');
await page.touchscreen.tap(270, 480);
await delay(300);

// 1 — THE TOWER. The hook, with no explanation needed.
await tower(90, 520);
await page.evaluate(() => window.CAIRN.monument(true));
await delay(2600);
// The share chip belongs to the game, not to the listing. It appears once the
// pull-back lands, which is exactly when this photograph is taken.
await page.evaluate(() => { document.getElementById('monshare').className = ''; });
await shoot('01-the-tower', 'Every death leaves a stone', 'top');
await page.evaluate(() => window.CAIRN.monument(false));
await delay(900);

// 2 — the climb itself, mid-tower.
await tower(40, 300);
await page.evaluate(() => {
  const { sim, camera } = window.CAIRN;
  sim.body.y = 190; sim.body.x = 52; sim.body.grounded = true;
  camera.y = 190;
});
await delay(400);
await shoot('02-the-climb', 'One thumb. Drag to aim, release to jump.', 'bottom');

// 3 — aiming, with the predicted arc.
// Playwright's touchscreen has `tap` and nothing else, so a HELD drag needs the
// pointer events — the one place in this repository where synthetic dispatch is
// acceptable, because this is a photograph and not a test of the input path.
// Everything that asserts input still goes through page.touchscreen.
await page.evaluate(() => {
  const v = document.getElementById('view');
  const at = (type, x, y) => v.dispatchEvent(new PointerEvent(type, {
    pointerId: 1, clientX: x, clientY: y, bubbles: true, cancelable: true, pointerType: 'touch',
  }));
  at('pointerdown', 270, 640);
  at('pointermove', 210, 400);
});
await delay(600);
await shoot('03-the-arc', 'The arc you see is the arc you fly', 'bottom');
await page.evaluate(() => {
  const v = document.getElementById('view');
  v.dispatchEvent(new PointerEvent('pointercancel', { pointerId: 1, bubbles: true, pointerType: 'touch' }));
});
await delay(300);

// 4 — a body being stood on. The premise, happening.
await page.evaluate(() => {
  const { sim, camera } = window.CAIRN;
  const c = sim.world.corpse(sim.body.x + 22, sim.body.y + 14, 0.2, 1, 0, sim.deaths);
  sim.body.x = c.x; sim.body.y = c.y + c.hh; sim.body.grounded = true; sim.body.standing = c;
  camera.y = sim.body.y;
});
await delay(400);
await shoot('04-stand-on-yourself', 'Climb on what you were', 'bottom');

// 5 — altitude: the biome shift, which is how height reads at a glance.
await tower(60, 900);
await page.evaluate(() => {
  const { sim, camera } = window.CAIRN;
  sim.body.y = 760; sim.body.x = 48; sim.body.grounded = true;
  camera.y = 760;
});
await delay(500);
await shoot('05-altitude', 'The world changes as you climb', 'top');

// 6 — the marks.
await page.evaluate(() => {
  const p = JSON.parse(localStorage.getItem('cairn.progress.v1') || '{}');
  p.marks = ['first_stone', 'ten_stones', 'stand', 'fifty', 'hundred', 'staircase', 'stood_ten'];
  p.best = 913; p.stones = 214; p.stood = 61; p.climbed = 41200; p.launches = 3180;
  p.streak = 6; p.bestStreak = 11; p.days = 23;
  localStorage.setItem('cairn.progress.v1', JSON.stringify(p));
});
await page.reload({ waitUntil: 'load' });
await page.waitForFunction(() => !!window.CAIRN);
await page.touchscreen.tap(270, 480);
await delay(400);
{
  const b = await page.locator('#menu').boundingBox();
  if (b) { await page.touchscreen.tap(b.x + b.width / 2, b.y + b.height / 2); await delay(400); }
  const marks = await page.locator('#panel .body .btn').nth(1).boundingBox();
  if (marks) { await page.touchscreen.tap(marks.x + marks.width / 2, marks.y + marks.height / 2); await delay(400); }
}
await shoot('06-marks', 'Thirty marks. Most are about the tower.', 'top');

// 7 — statistics.
{
  const back = await page.locator('#panel .foot .btn').boundingBox();
  if (back) { await page.touchscreen.tap(back.x + back.width / 2, back.y + back.height / 2); await delay(350); }
  const stats = await page.locator('#panel .body .btn').nth(0).boundingBox();
  if (stats) { await page.touchscreen.tap(stats.x + stats.width / 2, stats.y + stats.height / 2); await delay(400); }
}
await shoot('07-statistics', 'Numbers that only grow', 'top');

// 8 — the daily climb.
{
  const back = await page.locator('#panel .foot .btn').boundingBox();
  if (back) { await page.touchscreen.tap(back.x + back.width / 2, back.y + back.height / 2); await delay(350); }
  const resume = await page.locator('#panel .foot .btn').boundingBox();
  if (resume) { await page.touchscreen.tap(resume.x + resume.width / 2, resume.y + resume.height / 2); await delay(350); }
}
await page.evaluate(() => window.CAIRN.setMode(true));
await delay(400);
await tower(30, 240);
await delay(400);
await shoot('08-daily', 'One tower a day. The same one for everyone.', 'bottom');

console.log(`\n  8 screenshots in ${OUT}/ at ${W}x${H}`);
await browser.close();
shutdown();
